## 2. Plan de Pruebas: Unitarias, Integración y E2E

### 2.1. Pruebas Unitarias (Vitest + React Testing Hooks)
Se validará que el hook personalizado `useRealtimeSync` maneje correctamente las suscripciones, la limpieza de canales al desmontar componentes y la validación de esquemas Zod ante payloads malformados.

```typescript
// __tests__/useRealtimeSync.test.ts
import { renderHook, act } from '@testing-library/react';
import { describe, it, expect, vi, beforeEach } from 'vitest';
import { useRealtimeSync } from '../src/hooks/useRealtimeSync';
import { supabase } from '../src/lib/supabase';

// Mock de Supabase Client Realtime
vi.mock('../src/lib/supabase', () => ({
  supabase: {
    channel: vi.fn(() => ({
      on: vi.fn().mockReturnThis(),
      subscribe: vi.fn((callback) => {
        callback('SUBSCRIBED');
        return { unsubscribe: vi.fn() };
      }),
    })),
    removeChannel: vi.fn(),
  },
}));

describe('SPEC-045: useRealtimeSync Unit Tests', () => {
  beforeEach(() => {
    vi.clearAllMocks();
  });

  it('debe suscribirse exitosamente al canal de inventario filtrado por tenant_id', () => {
    const tenantId = '123e4567-e89b-12d3-a456-426614174000';
    const onDataChange = vi.fn();

    renderHook(() => useRealtimeSync({ table: 'inventario_lotes', tenantId, onDataChange }));

    expect(supabase.channel).toHaveBeenCalledWith(`public:inventario_lotes:tenant_id=eq.${tenantId}`);
  });

  it('debe descartar payloads que fallen en la validación del esquema Zod', async () => {
    let changeCallback: any;
    vi.mocked(supabase.channel).mockReturnValueOnce({
      on: vi.fn((event, filter, callback) => {
        changeCallback = callback;
        return { subscribe: vi.fn() };
      }),
      subscribe: vi.fn((cb) => cb('SUBSCRIBED')),
    } as any);

    const onDataChange = vi.fn();
    renderHook(() => useRealtimeSync({ table: 'inventario_lotes', tenantId: '123...', onDataChange }));

    // Simular payload inválido (peso negativo)
    const invalidPayload = {
      schema: 'public',
      table: 'inventario_lotes',
      eventType: 'UPDATE',
      commit_timestamp: new Date().toISOString(),
      errors: null,
      new: { id: 'uuid', tenant_id: '123...', peso_actual_kg: -5, estado: 'DISPONIBLE' },
      old: {},
    };

    act(() => {
      changeCallback(invalidPayload);
    });

    expect(onDataChange).not.toHaveBeenCalled();
  });
});
```

